from pathlib import Path
import json,hashlib,datetime
p=Path('tests/.work/T19-dirty-output-summary.json');d=json.loads(p.read_text());sha=lambda b:hashlib.sha256(b).hexdigest()
for row in d['coverage']:assert sha(Path(row['png_path']).read_bytes())==row['png_sha256']
record={'task':'T19','reviewer':'root','method':'Actual tools.view_image inspection of all ten representative full-page PNGs; exact decoded RGB pixel grouping covers all 48 rendered pages across two dirty native shell runs. Typed observations are not an automated visual validator.','summary_sha256':sha(p.read_bytes()),'reviewed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewed_groups':d['pixel_groups'],'coverage':d['coverage'],'observations':['All pages readable with identifiers, headings, static phrases, field values, borders, highlights and note icons.','Masters have exact original page RGB pixels.','Screen renders page2/page4 text upright in portrait effective dimensions.','Ebook page2/page4 remain sideways in landscape effective dimensions; note icons differ from originals.','Email visible values do not establish editable canonical fields/widgets.'], 'limitations':['No attachment opened or URI followed.','No physical Explorer, GUI form-editing, accessibility, signature, PDF/A or malware validation.','This controlled vector/text corpus is not general image fidelity or archival certification.'],'result':'completed scoped visual observations'}
Path('tests/.work/T19-dirty-visual-review.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':record['result'],'pages':len(d['coverage']),'groups':len(d['pixel_groups'])}))
